/**
 * i18n-content.js — single source of truth for the content matrix
 * (tools, cheat sheets, recipes, collection, deals).
 *
 * Pages mark up localizable strings with data-i18n="key". On DOMContentLoaded
 * the active language's value replaces the text node. Unknown keys are left
 * as-is so a partial dictionary never produces empty UI.
 *
 * Adding a new page? Two steps only:
 *   1. Markup the HTML with data-i18n="your.key"
 *   2. Add the same key to TRANSLATIONS.en and TRANSLATIONS.cn below
 *
 * The header/nav/footer chrome is generated by normalize-nav.mjs; this file
 * covers body content only.
 */

